Do we not need the default export since we import the renderer and use its draw method in the diagram definition?

```
import renderer from './requirementRenderer.js';

export const diagram: DiagramDefinition = {
  parser,
  get db() {
    return new RequirementDB();
  },
  renderer,
  styles,
};
```

```
export interface DiagramDefinition {
  db: DiagramDB;
  renderer: DiagramRenderer;
  parser: ParserDefinition;
  ...
```

```
export interface DiagramRenderer {
  draw: DrawDefinition;
  getClasses?: (
    text: string,
    diagram: Pick<DiagramDefinition, 'db'>
  ) => Map<string, DiagramStyleClassDef>;
}
```
